/**
 * OpenAPI 3.0.3 specification — the single source of truth for this API's docs.
 *
 * Hand-authored rather than generated by swagger-autogen, for three reasons:
 *   1. autogen produced Swagger 2.0 with no request/response schemas at all,
 *      which for money endpoints is close to useless.
 *   2. Generating it required booting server.js, which needs a live MongoDB.
 *   3. It silently fell out of date — it documented 9 of 47 routes.
 *
 * This module is served directly by /api-docs (so the docs are always in sync
 * with what ships), written to swagger-output.json by `npm run swagger`, and
 * converted into the Postman collection by `npm run postman`.
 *
 * Amounts: every request takes rupees (`amount`), every response returns both
 * `amount` (rupees) and `amountPaise` (exact integer). See src/utils/money.js.
 */

const ref = (name) => ({ $ref: `#/components/schemas/${name}` });

const jsonBody = (schema, example) => ({
  required: true,
  content: { 'application/json': { schema, ...(example ? { example } : {}) } },
});

const jsonResponse = (description, schema, example) => ({
  description,
  content: { 'application/json': { schema, ...(example ? { example } : {}) } },
});

const MPIN = { type: 'string', pattern: '^\\d{4,6}$', example: '1234', description: '4-6 digit MPIN' };
const RUPEES = {
  oneOf: [{ type: 'number' }, { type: 'string' }],
  example: 250.5,
  description: 'Amount in rupees, max 2 decimal places. Rejected with 400 if more precise.',
};

/** Reusable error responses, referenced by name from each operation. */
const RESPONSES = {
  ValidationFailed: jsonResponse('Request body failed validation', ref('ValidationError'), {
    message: 'Validation failed',
    errors: ['"amount" must be greater than zero', 'MPIN must be 4-6 digits'],
  }),
  Unauthorized: jsonResponse('Missing, invalid, revoked or expired token', ref('Error'), {
    message: 'Not authorized, no token',
  }),
  IncorrectMpin: jsonResponse('Incorrect MPIN (attemptsLeft counts down to lockout)', ref('MpinError'), {
    message: 'Incorrect MPIN',
    attemptsLeft: 4,
  }),
  Forbidden: jsonResponse('Authenticated but not permitted to act on this resource', ref('Error'), {
    message: 'You are not authorized to view this transaction',
  }),
  NotFound: jsonResponse('Resource not found', ref('Error'), { message: 'Transaction not found' }),
  Conflict: jsonResponse('Resource is not in a state that allows this action', ref('Error'), {
    message: 'This request is already accepted',
  }),
  RateLimited: jsonResponse('Rate limited, or MPIN lockout active', ref('Error'), {
    message: 'Too many incorrect MPIN attempts. Try again in 15 minute(s).',
  }),
  ServerError: jsonResponse('Unexpected error (consistent shape, never a stack trace)', ref('Error'), {
    message: 'Something went wrong on our end',
    requestId: '9f1c2b3a-...',
  }),
};

const errorRefs = (...names) =>
  names.reduce((acc, name) => {
    const code = {
      ValidationFailed: '400',
      Unauthorized: '401',
      IncorrectMpin: '401',
      Forbidden: '403',
      NotFound: '404',
      Conflict: '409',
      RateLimited: '429',
      ServerError: '500',
    }[name];
    acc[code] = { $ref: `#/components/responses/${name}` };
    return acc;
  }, {});

/** Query parameters shared across list endpoints. */
const PARAMS = {
  page: {
    name: 'page',
    in: 'query',
    schema: { type: 'integer', minimum: 1, default: 1 },
    description: 'Page number (1-based)',
  },
  limit: {
    name: 'limit',
    in: 'query',
    schema: { type: 'integer', minimum: 1, maximum: 100, default: 10 },
    description: 'Page size. Hard-capped at MAX_PAGE_SIZE (100) server-side.',
  },
  IdempotencyKey: {
    name: 'Idempotency-Key',
    in: 'header',
    required: false,
    schema: { type: 'string' },
    description:
      'Optional. Repeating a request with the same key replays the original response instead of moving money twice — send one per logical payment attempt.',
  },
  RequestId: {
    name: 'X-Request-Id',
    in: 'header',
    required: false,
    schema: { type: 'string' },
    description: 'Correlation id. Echoed back on the response and attached to every log line for the request.',
  },
};

